import math

def is_perfect_cube(n):
    if n < 0:
        # Handle negative numbers: check if -n is a perfect cube, and then negate the result.
        # Or more directly, find the cube root of |n| and check if it's an integer,
        # then ensure the sign is correct.
        abs_n = abs(n)
        root = round(abs_n**(1/3))
        if root**3 == abs_n:
            return True, -root
        else:
            return False, None
    else:
        root = round(n**(1/3))
        if root**3 == n:
            return True, root
        else:
            return False, None

solutions = {}
for x in range(-10, 11):
    E_x = (8 * x - 41) * (x + 3)**2
    is_cube, root = is_perfect_cube(E_x)

    solutions[x] = {
        'E(x)': E_x,
        'is_cube': is_cube,
        'cube_root': root
    }

print("Results for x from -10 to 10:")
for x, data in solutions.items():
    print(f"x = {x}: E(x) = {data['E(x)']}, Is Cube? {data['is_cube']}, Cube Root = {data['cube_root']}")

print("\nSolutions found (x values where E(x) is a perfect cube):")
solutions_list = [x for x, data in solutions.items() if data['is_cube']]
print(solutions_list)

import math

def is_perfect_cube(n):
    if n == 0:
        return True
    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Approximate the cube root
    root = round(n**(1/3))

    # Check if the cube is exact
    return (root**3 == n)

